param([Parameter(Mandatory=$true)][string]$MinecraftJar,[Parameter(Mandatory=$true)][string]$BetterCombatJar,[string]$MinecraftAssets)
$ErrorActionPreference='Stop'
$nativeRootTask=Split-Path $PSScriptRoot -Parent
$assetsTask=Join-Path $nativeRootTask 'artifacts/StandaloneAssets'
$cacheTask=Join-Path $nativeRootTask 'dependencies/native-resources'
$manifestTask=Join-Path $assetsTask 'native-audio-v4.json'
if(Test-Path -LiteralPath $manifestTask){$priorAudioTask=Get-Content -LiteralPath $manifestTask -Raw | ConvertFrom-Json;if($priorAudioTask.eventsVersion -ge 12){return}}
Add-Type -AssemblyName System.IO.Compression.FileSystem
$lockTask=Get-Content -LiteralPath (Join-Path $nativeRootTask 'release/native-dependencies.lock.json') -Raw | ConvertFrom-Json
$candidatesTask=@($MinecraftAssets,(Join-Path $env:APPDATA '.minecraft/assets'),(Join-Path ${env:ProgramFiles(x86)} 'MC/.minecraft/assets')) | Where-Object {$_ -and (Test-Path -LiteralPath (Join-Path $_ 'indexes/5.json'))}
$localTask=$candidatesTask | Select-Object -First 1
$indexTask=if($localTask){Join-Path $localTask 'indexes/5.json'}else{Join-Path $cacheTask 'minecraft-sounds-index-5.json'}
[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
if(-not(Test-Path -LiteralPath $indexTask)){Invoke-WebRequest -UseBasicParsing -Uri $lockTask.minecraftSoundsIndex.url -OutFile $indexTask -TimeoutSec 120}
if(-not $localTask -and (Get-FileHash -LiteralPath $indexTask -Algorithm SHA1).Hash -ne $lockTask.minecraftSoundsIndex.sha1){throw 'Sound asset index checksum mismatch.'}
$objectsTask=(Get-Content -LiteralPath $indexTask -Raw | ConvertFrom-Json).objects
$audioTask=Join-Path $assetsTask 'mc_audio';New-Item -ItemType Directory -Path $audioTask -Force | Out-Null
$manifestDataTask=@{}
function NativeAudioKeyTask([string]$Path){$keyTask=(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant();$targetTask=Join-Path $audioTask ($keyTask+'.ogg');if(-not(Test-Path -LiteralPath $targetTask)){Copy-Item -LiteralPath $Path -Destination $targetTask};return $keyTask}
function NativeAudioObjectTask([string]$Name){$entryTask=$objectsTask.PSObject.Properties[$Name];if(-not $entryTask){throw ('Missing sound-index entry: '+$Name)};$hashTask=$entryTask.Value.hash;$pathTask=if($localTask){Join-Path $localTask ('objects/'+$hashTask.Substring(0,2)+'/'+$hashTask)}else{Join-Path $cacheTask ('sound-object-'+$hashTask)};if(-not(Test-Path -LiteralPath $pathTask)){$pathTask=Join-Path $cacheTask ('sound-object-'+$hashTask);if(-not(Test-Path -LiteralPath $pathTask)){Invoke-WebRequest -UseBasicParsing -Uri ('https://resources.download.minecraft.net/'+$hashTask.Substring(0,2)+'/'+$hashTask) -OutFile $pathTask -TimeoutSec 60}};if((Get-FileHash -LiteralPath $pathTask -Algorithm SHA1).Hash -ne $hashTask){throw 'Static sound object checksum mismatch.'};return $pathTask}
$zipTask=[IO.Compression.ZipFile]::OpenRead($MinecraftJar)
try{$entryTask=$zipTask.GetEntry('assets/minecraft/sounds.json');if($entryTask){$readerTask=[IO.StreamReader]::new($entryTask.Open());try{$definitionsTask=$readerTask.ReadToEnd() | ConvertFrom-Json}finally{$readerTask.Dispose()}}else{$definitionsTask=Get-Content -LiteralPath (NativeAudioObjectTask 'minecraft/sounds.json') -Raw | ConvertFrom-Json}}finally{$zipTask.Dispose()}
function NativeSoundNamesTask([string]$Id,[int]$Depth=0){if($Depth -gt 8){return};$idTask=$Id -replace '^minecraft:','';$definitionTask=$definitionsTask.PSObject.Properties[$idTask];if(-not $definitionTask){return};foreach($soundTask in $definitionTask.Value.sounds){if($soundTask -is [string]){$soundTask -replace '^minecraft:',''}elseif($soundTask.type -eq 'event'){NativeSoundNamesTask $soundTask.name ($Depth+1)}else{$soundTask.name -replace '^minecraft:',''}}}
$wantedTask=@('entity.player.hurt','entity.player.death','entity.player.attack.strong','entity.player.attack.weak','entity.player.attack.sweep','entity.player.attack.crit','entity.arrow.shoot','entity.arrow.hit','entity.arrow.hit_player','item.shield.block','item.shield.break','item.totem.use','entity.tnt.primed','entity.generic.explode','entity.player.burp','entity.generic.eat','entity.generic.drink','item.bucket.fill','item.bucket.empty','item.bucket.fill_lava','item.bucket.empty_lava','entity.enderman.teleport','entity.generic.splash','entity.splash_potion.throw','entity.splash_potion.break','entity.lingering_potion.throw','entity.firework_rocket.launch','block.anvil.use','block.enchantment_table.use','block.grindstone.use','block.brewing_stand.brew','ui.button.click')
foreach($materialTask in @('stone','wood','gravel','sand','grass','glass','metal')){foreach($actionTask in @('place','break','step')){$wantedTask+='block.'+$materialTask+'.'+$actionTask}}
foreach($idTask in $wantedTask){$keysTask=@();foreach($nameTask in @(NativeSoundNamesTask $idTask | Select-Object -Unique)){$objectTask=$objectsTask.PSObject.Properties[('minecraft/sounds/'+$nameTask+'.ogg')];if(-not $objectTask){continue};$hashTask=$objectTask.Value.hash;$pathTask=if($localTask){Join-Path $localTask ('objects/'+$hashTask.Substring(0,2)+'/'+$hashTask)}else{Join-Path $cacheTask ('sound-'+$hashTask+'.ogg')};if(-not(Test-Path -LiteralPath $pathTask)){$pathTask=Join-Path $cacheTask ('sound-'+$hashTask+'.ogg');if(-not(Test-Path -LiteralPath $pathTask)){Invoke-WebRequest -UseBasicParsing -Uri ('https://resources.download.minecraft.net/'+$hashTask.Substring(0,2)+'/'+$hashTask) -OutFile $pathTask -TimeoutSec 60}};if((Get-FileHash -LiteralPath $pathTask -Algorithm SHA1).Hash -ne $hashTask){throw 'Sound asset checksum mismatch.'};$keysTask+=NativeAudioKeyTask $pathTask};if($keysTask.Count){$manifestDataTask['minecraft:'+$idTask]=@($keysTask)}}
$zipTask=[IO.Compression.ZipFile]::OpenRead($BetterCombatJar)
try{$readerTask=[IO.StreamReader]::new($zipTask.GetEntry('assets/bettercombat/sounds.json').Open());try{$definitionsTask=$readerTask.ReadToEnd() | ConvertFrom-Json}finally{$readerTask.Dispose()};foreach($definitionTask in $definitionsTask.PSObject.Properties){$keysTask=@();foreach($soundTask in $definitionTask.Value.sounds){$nameTask=if($soundTask -is [string]){$soundTask}else{$soundTask.name};$nameTask=$nameTask -replace '^bettercombat:','';if($nameTask.Contains('..')){continue};$entryTask=$zipTask.GetEntry('assets/bettercombat/sounds/'+$nameTask+'.ogg');if(-not $entryTask){continue};$pathTask=Join-Path $cacheTask 'bc-sound-extract.ogg';[IO.Compression.ZipFileExtensions]::ExtractToFile($entryTask,$pathTask,$true);$keysTask+=NativeAudioKeyTask $pathTask};if($keysTask.Count){$manifestDataTask['bettercombat:'+$definitionTask.Name]=@($keysTask)}}}finally{$zipTask.Dispose()}
@{schema=1;eventsVersion=12;source=$(if($localTask){'local installed asset index; each object hash checked'}else{'official pinned asset index'});indexSha1=(Get-FileHash -LiteralPath $indexTask -Algorithm SHA1).Hash.ToLowerInvariant();sounds=$manifestDataTask} | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $manifestTask -Encoding UTF8
Write-Output ('Native static audio ready: '+$manifestDataTask.Count+' sound events. No game/Java started.')
